$function$
CREATE OR REPLACE FUNCTION public.consume_bespoke_request_rate_limit(p_ip_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now TIMESTAMPTZ := clock_timestamp();
  v_request_count INTEGER;
BEGIN
  IF p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Invalid IP hash';
  END IF;

  INSERT INTO public.bespoke_request_rate_limits AS rate_limit (
    ip_hash,
    window_started_at,
    request_count
  )
  VALUES (p_ip_hash, v_now, 1)
  ON CONFLICT (ip_hash) DO UPDATE SET
    window_started_at = CASE
      WHEN rate_limit.window_started_at <= v_now - INTERVAL '1 hour'
        THEN v_now
      ELSE rate_limit.window_started_at
    END,
    request_count = CASE
      WHEN rate_limit.window_started_at <= v_now - INTERVAL '1 hour'
        THEN 1
      ELSE rate_limit.request_count + 1
    END
  RETURNING request_count INTO v_request_count;

  RETURN v_request_count <= 5;
END;
$function$
CREATE OR REPLACE FUNCTION public.consume_checkout_rate_limit(p_ip_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_now TIMESTAMPTZ := clock_timestamp(); v_count INTEGER;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid rate limit key'; END IF;
  INSERT INTO public.checkout_rate_limits AS limits (ip_hash, window_started_at, request_count)
  VALUES (p_ip_hash, v_now, 1)
  ON CONFLICT (ip_hash) DO UPDATE SET
    window_started_at = CASE WHEN limits.window_started_at <= v_now - INTERVAL '1 hour' THEN v_now ELSE limits.window_started_at END,
    request_count = CASE WHEN limits.window_started_at <= v_now - INTERVAL '1 hour' THEN 1 ELSE limits.request_count + 1 END
  RETURNING request_count INTO v_count;
  RETURN v_count <= 12;
END;
$function$
